mapper.select:
select ve.VENUES_NAME as venuesName, (select dict.DICT_CN_DESC from RM_SYS_DICT dict where dict.DICT_TYPE_CD='5001' and dict.DICT_CD=tc.CO_COLOR) as coColorNm, (select dict.DICT_CN_DESC from RM_SYS_DICT dict where dict.DICT_TYPE_CD='5002' and dict.DICT_CD=tc.CO_TYPE) as coTypeNm, (select dict.DICT_CN_DESC from RM_SYS_DICT dict where dict.DICT_TYPE_CD='7001' and dict.DICT_CD=tc.CO_STATE) as coStateNm, DATE_FORMAT(tc.CO_OCCUR_TM,'%Y-%m-%d %H:%i:%s') as occurTm, DATE_FORMAT(tc.CO_HANDLE_TM,'%Y-%m-%d %H:%i:%s') as handleTm, tc.CO_ID as coId, tc.CO_CONTENT as coContent, tc.CO_PROGRESS as coProgress, tc.CO_REMARK as coRemark, tc.CO_COLOR as coColor, tc.CO_TYPE as coType, tc.CO_STATE as coState, ve.VENUES_ID as coVenuesId, tc.CO_OCCUR_TM as coOccurTm, tc.CO_HANDLE_TM as coHandleTm, tc.CO_ID as coId from RM_THREE_COLOR tc left join RM_VENUES_INFO ve on ve.VENUES_ID=tc.CO_VENUES_ID
tc.CO_VALID='1'
and tc.CO_COLOR=#{vo.searchOne}
and tc.CO_TYPE=#{vo.searchTwo}
AND ve.TOWN = #{vo.town}
AND ve.AREA = #{vo.area}
and ve.VENUES_ID IN
#{value}
limit #{vo.page},#{vo.size}

SELECT
    count(tc.CO_ID)
from RM_THREE_COLOR tc
left join RM_VENUES_INFO ve on ve.VENUES_ID=tc.CO_VENUES_ID

    tc.CO_VALID='1'

        and tc.CO_COLOR=#{vo.searchOne}


        and tc.CO_TYPE=#{vo.searchTwo}


        AND  ve.TOWN = #{vo.town}


        AND  ve.AREA = #{vo.area}


        and ve.VENUES_ID IN

            #{value}
